 lower demand","event_peaks":"Jan-Feb German Channel manta aggregations","campaign_start":"season fire Aug-Sep; manta-week fire Oct-Nov"},"jewels":[{"name":"Blue Corner","si_tag":"liveaboard","status":"live","tier":"premier","hook":"the legendary reef-hook shark drift, visibility up to ~90 ft","bookable_category":"liveaboard berth","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"the legendary reef-hook shark drift, visibility up to ~90 ft","when":"Nov-May","commission":"fleet-direct (Aggressor/Explorer)"},{"name":"German Channel","si_tag":"liveaboard","status":"live","tier":"premier","hook":"manta cleaning station; dozens of mantas in Jan-Feb","bookable_category":"liveaboard berth","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"manta cleaning station; dozens of mantas in Jan-Feb","when":"Nov-May","commission":"fleet-direct"},{"name":"Ulong Channel","si_tag":"liveaboard","status":"live","tier":"premier","hook":"a premier drift past giant clams and lettuce coral","bookable_category":"liveaboard berth","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"a premier drift past giant clams and lettuce coral","when":"Nov-May","commission":"fleet-direct"},{"name":"Blue Holes","si_tag":"liveaboard","status":"live","tier":"premier","hook":"cathedral cavern of light beams into a wall","bookable_category":"liveaboard berth","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"cathedral cavern of light beams into a wall","when":"Nov-May","commission":"fleet-direct"},{"name":"Peleliu Wall / Peleliu Express","si_tag":"liveaboard","status":"live","tier":"premier","hook":"deep wall and strong-current corner off the WWII island","bookable_category":"liveaboard berth","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"deep wall and strong-current corner off the WWII island","when":"Nov-May","commission":"fleet-direct"},{"name":"Siaes Tunnel / Corner","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"cavern-tunnel and wall dive","bookable_category":"liveaboard berth","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"cavern-tunnel and wall dive","when":"Nov-May","commission":"fleet-direct"},{"name":"New Drop-Off","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"wall-and-plateau reef with sharks in current","bookable_category":"liveaboard berth","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"wall-and-plateau reef with sharks in current","when":"Nov-May","commission":"fleet-direct"},{"name":"Big Drop-Off","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"a sheer wall off Ngemelis","bookable_category":"liveaboard berth","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"a sheer wall off Ngemelis","when":"Nov-May","commission":"fleet-direct"},{"name":"Chandelier Cave","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"a cavern with air chambers and stalactites","bookable_category":"liveaboard berth","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"a cavern with air chambers and stalactites","when":"Nov-May","commission":"fleet-direct"},{"name":"German Channel manta route (Dec-Mar)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"the winter manta-aggregation week","bookable_category":"liveaboard week","source":"https://palaudiveadventures.com/dive-palau/","si":"liveaboard","blurb":"the winter manta-aggregation week","commission":"fleet-direct (Aggressor/Explorer)"},{"name":"Blue Corner + Blue Holes + Ngemelis wall route","si_tag":"liveaboard","status":"live","tier":"premier","hook":"the classic marquee-wall liveaboard arc","bookable_category":"liveaboard week","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"the classic marquee-wall liveaboard arc","when":"Nov-May","commission":"fleet-direct (Aggressor/Explorer)"},{"name":"Peleliu WWII battlefield + Rock Islands (UNESCO)","si_tag":"globaladv","status":"future","tier":"premier","hook":"the WWII island ashore and the Rock Islands Southern Lagoon seascape","bookable_category":"DMC / liveaboard-included excursion","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"the WWII island ashore and the Rock Islands Southern Lagoon seascape","when":"Nov-May","commission":"DMC / excursion pass-through"},{"name":"Jellyfish Lake (Ongeim''l Tketau)","si_tag":"ocean","status":"future","tier":"premier","hook":"the permit-based golden-jellyfish lake; snorkel-only, scuba prohibited","bookable_category":"permit / DMC","source":"https://palaudiveadventures.com/dive-palau/","timing":"Nov-May","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"the permit-based golden-jellyfish lake; snorkel-only, scuba prohibited","when":"Nov-May","commission":"permit / DMC pass-through"}],"faq":[{"q":"What is the current advisory for Palau, and how do I dive it responsibly?","a":"The U.S. State Department places Palau at Level 1 - Exercise Normal Precautions, and the UK FCDO issues no advice against travel, describing crime levels as low. Both note practical hazards rather than restrictions: unexploded WWII ordnance (found mainly on Peleliu - stay on marked paths and do not touch ordnance), diving hazards, and tropical cyclones, with an overnight curfew in Koror. The two governments agree on a Level 1 posture. Carry DAN membership plus dive-accident insurance with strong evacuation cover - the Palau Siren operator stresses that insurance covering emergency evacuation, chamber treatment and medical costs is a must - and observe an 18-24 hour no-fly window after diving.","source":"travel.state.gov/content/travel/en/traveladvisories/traveladvisories/palau-travel-advisory.html + gov.uk/foreign-travel-advice/palau/safety-and-security + masterliveaboards.com/faq/palau (all accessed 2026-08-09)","si_tag":"safety"},{"q":"Is there a recompression chamber, and how remote is care?","a":"Palau has one hyperbaric facility for divers - a recompression chamber at Belau National Hospital in Koror. Hospital sources describe it as operational in 2026 with a trained barotrauma team, but availability can vary, so confirm its status with your dive operator or DAN before the trip. Because the archipelago is dispersed, serious cases can require evacuation by speedboat from the vessel and, in some cases, onward air evacuation to Manila - which is why evacuation-grade dive insurance matters here.","source":"masterliveaboards.com/faq/palau (accessed 2026-08-09)","si_tag":"safety"},{"q":"When is the best time to dive Palau, and when do the mantas aggregate?","a":"The peak liveaboard season is November through May, with warm water (28-30C) year-round. For mantas at German Channel, the winter months are best - January and February can bring dozens of mantas to the cleaning station.","source":"masterliveaboards.com/faq/palau + palaudiveadventures.com/dive-palau","si_tag":"planning"},{"q":"Which sites define a Palau liveaboard week?","a":"Blue Corner (the reef-hook shark drift), German Channel (mantas), Ulong Channel (a drift past giant clams and lettuce coral), the Blue Holes cavern, the Peleliu walls, Siaes Tunnel and New Drop-Off - plus the snorkel-only Jellyfish Lake as a non-dive highlight.","source":"palaudiveadventures.com/dive-palau","si_tag":"liveaboard"},{"q":"What conditions and certification should I plan for?","a":"Blue Corner, Peleliu Express and the channel dives are strong-current drift dives where a reef hook and good buoyancy are essential, best suited to experienced divers; sheltered reefs, Chandelier Cave and the lake suit a wider range with a guide. Nitrox is standard on liveaboards for the multi-day profile. Dive within your certification and the operator briefing.","source":"palaudiveadventures.com/dive-palau","si_tag":"liveaboard"},{"q":"How far ahead do Palau liveaboards book?","a":"The November-May peak on the marquee vessels fills earliest, with the January-February manta weeks in most demand; hold roughly 6-12 months out for peak windows and preferred boats, nearer term for the shoulder. Confirm per-vessel lead times with the operator.","source":"masterliveaboards.com/faq/palau","si_tag":"planning"}],"seo":{"meta_title":"Palau Liveaboard Diving: Blue Corner, Mantas & Season","meta_description":"The Palau liveaboard sea - Blue Corner''s reef-hook shark drift, the German Channel mantas, Blue Holes and the Peleliu walls, the Nov-May season, operators and safety.","slug":"palau-micronesia","primary_keyword":"Palau liveaboard diving","long_tail":["Blue Corner Palau","German Channel manta","Palau dive season","Peleliu wall dive","Palau liveaboard operators"],"search_language":"en","local_keywords":["Palau diving","Blue Corner","German Channel manta"],"hreflang":["en"],"jsonld_type":"TouristDestination","content_freshness":"2026-08-09"},"booking":{"bin":"freely bookable (L1)","level":"L1 (Exercise Normal Precautions)","codes":["L1"],"note":"US State Dept Level 1 (Exercise Normal Precautions), accessed 2026-08-09 (travel.state.gov/content/travel/en/.../palau-travel-advisory.html). FCDO cross-check (gov.uk/foreign-travel-advice/palau/safety-and-security, accessed 2026-08-09): no advice against travel; crime levels low; terrorism cannot be ruled out but no recent history. Both flag unexploded WWII ordnance (mainly Peleliu) + diving/tropical-cyclone hazards. Both at L1 posture."},"si_checklist_25":{"run_date":"2026-08-09","hits":4,"misses":18,"disregarded":3,"note":"Liveaboard-diving scope; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"liveaboard","name":"liveaboard","status":"live"},{"si":"globaladv","name":"adventure","status":"future"},{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"ocean","name":"ocean","status":"future"}],"ultra":[{"name":"Private full-boat charter (Palau Aggressor II or Palau Siren) across the marquee walls + German Channel manta weeks + Rock Islands/Peleliu land layer + Koror pre/post","why_ultra":"the Palau ultra pull is a private full-boat charter pairing the marquee walls, the manta channel and the WWII/Rock Islands layer ashore","earning":"held Aggressor/Explorer reseller lines; verify Master/charter terms","virtuoso_value_add":"verify - not documented","mor":"commission-on-net; no net-rate resale markup","source":"handoff/LIVEABOARD-OPERATOR-GRID-2026-08-09.md"}],"source_verified":"2026-08-09","hero":{"query":"Palau, Palau"},"geo":{"lat":7.34,"lng":134.48}}'::jsonb, 3),
  ('machu-picchu-peru', '10S', 'Machu Picchu', 'Peru', 'A lost city in the clouds', 'live', 'verified', 'mountainValley', 'Cusco, Sacred Valley & Machu Picchu', '{"expedition","romance","culture"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Machu Picchu citadel sits at 2,430 m; Cusco gateway at ~3,400 m — altitude, not crime, is the headline planning constraint.","Entry is by timed circuit ticket only (no free roaming); daily cap 4,500 standard / 5,600 high season (Jun 19–Nov 2).","Classic Inca Trail is guided-mandatory, capped at 500 permits/day (~200 hikers), sells out 4–7 months ahead, and closes every February.","Cusco / Sacred Valley / Inca Trail / Machu Picchu are State-Dept-named as NOT in any higher-risk advisory area — the strongest clean-zone in South America.","Rail from Ollantaytambo (~1h45m) via PeruRail/Inca Rail; the Belmond Hiram Bingham is the luxury tier and bundles citadel entry, bus and guide."],"safety":{"emergency":"105","emergency_ambulance":"117","tourist_line":"iPerú / Policía de Turismo","hospital":"Cusco private clinics for routine + altitude care; serious cases evac to Lima (Clínica Anglo Americana / Ricardo Palma); Aguas Calientes + trail remote","advisory_level":"L2","book_enabled":true,"bin":"freely bookable (L2)","air_access_verified":true,"air_access_note":"Cusco (CUZ) via Lima (LIM); then rail Ollantaytambo → Aguas Calientes; shuttle bus to the gate","altitude_m":{"cusco":3400,"citadel":2430,"sacred_valley_base":2800,"dead_womans_pass":4215,"salkantay_pass":4650,"rainbow_mountain":5000},"altitude_note":"Acute mountain sickness (soroche) is the primary health risk; acclimatize in the lower Sacred Valley first, ascend gradually, coca tea","water":"bottled/purified only","malaria":"none at altitude (Cusco/Sacred Valley/Machu Picchu); malaria risk is in the low-elevation Amazon","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel Within 20km south of the Peru-Colombia border FCDO advises against all but essential travel to areas within 20km south of the Putumayo River and the border between Peru and Colombia (Loreto region) except for: the Amazon River the area of the triple border with Brazil and Colombia from and including the towns of Caballococha in Peru up to the actual triple border at Santa Rosa de Yavari town Valley of the Apurímac, Ene, and Mantaro Rivers ( VRAEM ) FCDO advises against all but essential travel to the Valley of the Apurímac, Ene, and Mantaro Rivers, also known as the VRAEM region."},{"form":"against all but essential travel","text":"advise against all but essential travel to these two areas for safety and security reasons."},{"form":"against all but essential travel","text":"advises against all but essential travel to areas within 20km south of the Putumayo River and the border between Peru and Colombia (Loreto region) except for: the Amazon River the area of the triple border with Brazil and Colombia from and including the towns of Caballococha in Peru up to the actual triple border at Santa Rosa de Yavari town This is due to a high level of violence from organised criminal gangs who produce and traffic illegal drugs."},{"form":"against all but essential travel","text":"advises against all but essential travel to the Valley of the Apurímac, Ene and Mantaro Rivers, also known as the VRAEM region."},{"form":"against all but essential travel","text":"advises against all but essential travel."}],"url":"https://www.gov.uk/foreign-travel-advice/peru","read":"2026-08-19","page_updated":"2026-06-22T23:35:12+01:00"}},"timing":{"peak":"June–August (dry season; Jun–Jul apex; citadel cap 5,600 Jun 19–Nov 2)","inflection_curve_start":"early December (prior year); tickets release ~Nov 17","fire_date":"2026-11-24","shoulder":"April–May & September–October","green":"November–March (lush/wet; February = Inca Trail closed)","booking_lead":"Inca Trail 4–7 months for peak (6–7 Jun–Jul); citadel timed tickets weeks–months; marquee hotels + Hiram Bingham as early as the permit","off_season":"Nov–Mar green-season Salkantay/Lares + Vistadome rail packages","event_peaks":["Inti Raymi — Festival of the Sun, Cusco, June 24"]},"jewels":[{"name":"Dawn entry via the Sun Gate (Inti Punku)","si_tag":"GEA","status":"live","hook":"Inca Trail finishers walk in at first light — the most cinematic arrival at the citadel","bookable_category":"guided_trek_package","tier":"premier","source":"https://www.ticketmachupicchu.com/hiking-guide-sun-gate/","timing":"June–August","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Inca Trail finishers walk in at first light — the most cinematic arrival at the citadel","when":"June–August","commission":"direct-operator DMC via OutsideAgents/Fora"},{"name":"Huayna Picchu","si_tag":"GEA","status":"live","hook":"The iconic peak behind the postcard — straight-down views, 400 permits/day","bookable_category":"circuit_ticket_addon","tier":"comfort","source":"https://www.samtravelperu.com/index.php/peru-treks-machu-picchu-cuzco/huayna-picchu-mountain-availability-permits-information-machupicchu-mt-sun-gate-inka-bidge","timing":"June–August","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"The iconic peak behind the postcard — straight-down views, 400 permits/day","when":"June–August","commission":"DMC/tour add-on (ticket non-commissionable; guiding earns)"},{"name":"Machu Picchu Mountain","si_tag":"GEA","status":"live","hook":"Higher than Huayna, less exposed — big view without the ladders","bookable_category":"circuit_ticket_addon","tier":"comfort","source":"https://adventuresmithexplorations.com/land-tours/peru/machu-picchu-hike-options-explained/","timing":"June–August","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Higher than Huayna, less exposed — big view without the ladders","when":"June–August","commission":"DMC package"},{"name":"Salkantay Trek","si_tag":"GEA","status":"live","hook":"Glaciers + the 4,650 m pass + snow-to-jungle; ideal green-season fill","bookable_category":"trek_package","tier":"premier","source":"https://trexperienceperu.com/blog/salkantay-trek-vs-lares-trek","timing":"June–August","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Glaciers + the 4,650 m pass + snow-to-jungle; ideal green-season fill","when":"June–August","commission":"trek operator via OutsideAgents"},{"name":"Lares Trek","si_tag":"GEA","status":"live","hook":"The gentle cultural route through Quechua villages — quietest, most human","bookable_category":"trek_package","tier":"premier","source":"https://nickey-travel.com/blog/lares-trek-vs-salkantay/","timing":"June–August","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"The gentle cultural route through Quechua villages — quietest, most human","when":"June–August","commission":"trek operator via OutsideAgents"},{"name":"The Inca Bridge","si_tag":"GEA","status":"live","hook":"Short quiet cliff-edge walk to a defensive Inca bridge — low-effort secret","bookable_category":"included_in_ticket_walk","tier":"essential","source":"https://www.samtravelperu.com/index.php/peru-treks-machu-picchu-cuzco/huayna-picchu-mountain-availability-permits-information-machupicchu-mt-sun-gate-inka-bidge","timing":"year-round","timing_type":"ALWAYS-ON","si":"expedition","blurb":"Short quiet cliff-edge walk to a defensive Inca bridge — low-effort secret","when":"year-round","commission":"sold inside guided day tour"},{"name":"Putucusi","si_tag":"GEA","status":"live","hook":"Free, wild, ladder-climbed view across at the citadel — experienced hikers only","bookable_category":"free_unguided","tier":"essential","source":"https://www.ticketmachupicchu.com/alternatives-see-machu-picchu-from-above/","timing":"June–August","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Free, wild, ladder-climbed view across at the citadel — experienced hikers only","when":"June–August","commission":"none (content/SEO value only)"},{"name":"Belmond Hiram Bingham train","si_tag":"Romance","status":"live","hook":"Polished-brass luxe rail; bundles entry + bus + guide + gourmet dining","bookable_category":"luxury_rail","tier":"ultra","source":"https://www.belmond.com/trains/south-america/peru/belmond-hiram-bingham/","timing":"June–August","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Polished-brass luxe rail; bundles entry + bus + guide + gourmet dining","when":"June–August","commission":"Belmond/PeruRail via Fora/Virtuoso"},{"name":"Vistadome / 360 scenic trains","si_tag":"Romance","status":"live","hook":"Glass-roof panoramic cars — accessible romance below Hiram Bingham","bookable_category":"scenic_rail","tier":"premier","source":"https://heatherjasper.com/peru-blogs-travel-tips/machu-picchu-train","timing":"June–August","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Glass-roof panoramic cars — accessible romance below Hiram Bingham","when":"June–August","commission":"PeruRail/Inca Rail affiliate + DMC bundle"},{"name":"Aguas Calientes hot springs","si_tag":"Romance","status":"live","hook":"The town''s namesake thermal baths — a soak to unknot the legs post-trek","bookable_category":"entry_addon","tier":"essential","source":"https://www.perurail.com/","timing":"June–August","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"The town''s namesake thermal baths — a soak to unknot the legs post-trek","when":"June–August","commission":"affiliate/entry add-on"},{"name":"Inti Raymi — Festival of the Sun (Cusco, Jun 24)","si_tag":"Culture & Heritage","status":"future","hook":"Reconstructed Inca solstice ceremony at Sacsayhuamán — bucket-list cultural anchor","bookable_category":"festival_package","tier":"premier","source":"https://www.cuscoperu.com/en/festivities-events/may-june/inti-raymi/","timing":"June–August","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Reconstructed Inca solstice ceremony at Sacsayhuamán — bucket-list cultural anchor","when":"June–August","commission":"Cusco DMC festival package via OutsideAgents/Fora"}],"faq":[{"q":"What''s the real risk to plan for at Machu Picchu?","a":"Altitude, not crime. Cusco sits at ~3,400 m and acute mountain sickness (*soroche*) is the primary health risk — headache, nausea, breathlessness. Acclimatize in the lower Sacred Valley (~2,800 m) before Cusco or any trek, ascend gradually, and rest day one; the citadel itself (2,430 m) is lower, so many feel better there.","source":"alpacaexpeditions.com, 2026-07-07","si_tag":""},{"q":"How hard is the Inca Trail, and do I need a guide?","a":"You cannot legally hike the classic trail without a licensed guide, and it is demanding, not casual. Only 500 permits are issued per day (~200 hikers), the trail closes every February, and the Day-2 crux is Dead Woman''s Pass at 4,215 m — a ~1,200 m ascent where oxygen is ~60% of sea level. Book 4–7 months ahead for peak.","source":"incatrail.org / machupicchusoul.com, 2026-07-07","si_tag":"expedition"},{"q":"Is the Huayna Picchu climb dangerous?","a":"It''s exposed but managed — bookable for the sure-footed. Huayna Picchu is a ~2-hour climb capped at 400 permits/day, with big drop-offs, narrow original Inca stairs and cable-assisted sections; it is not for those uneasy with heights. Machu Picchu Mountain is the longer, higher, less-exposed alternative.","source":"samtravelperu.com, 2026-07-07","si_tag":"expedition"},{"q":"Is the Belmond Hiram Bingham worth it for a honeymoon?","a":"For a marquee honeymoon, yes — it removes the ticket-scramble. The Hiram Bingham bundles citadel entry, bus and guide into a ~1h45m polished-brass rail run, and pairs with the Sanctuary Lodge, the only hotel at the gate (first in at dawn, last out at dusk). Hold both as early as the trek permit.","source":"belmond.com / thesouthamericaspecialists.com, 2026-07-07","si_tag":"romance"},{"q":"When is the best time to visit Machu Picchu?","a":"May–October (dry season) is best and June–August is clearest — cloudless mornings — because the wet season (Nov–March) is lusher but rainier and February closes the Inca Trail entirely. The daily citadel cap also rises to 5,600 for the Jun 19–Nov 2 high-season block, so book early.","source":"salkantaytrekking.com / bushop.com, 2026-07-07","si_tag":"culture"}],"seo":{"jsonld_type":"TouristDestination","content_freshness":"2026-07-07","meta_title":"Machu Picchu, Peru — When to Go, Inca Trail Permits, Tickets & Where to Stay (2026)","search_language":"es-PE","local_keywords":["Machu Picchu entradas","Camino Inca permisos","cómo llegar a Machu Picchu","boletos Machu Picchu 2026 circuitos","mal de altura Cusco soroche","tren a Machu Picchu PeruRail","Salkantay o Lares","Huayna Picchu entradas","Valle Sagrado aclimatación","Inti Raymi Cusco 24 de junio"],"hreflang":["en","es-PE"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"romance","status":"live"},{"si":"culture","status":"future"}],"ultra":[{"name":"Sanctuary Lodge, A Belmond Hotel","why_ultra":"Only hotel adjacent to the citadel gate — first in at dawn, last out at dusk","earning":"Belmond commission via Fora/Virtuoso","virtuoso_value_add":"Bellini-Club perks: breakfast, credit, upgrades, priority dawn access","mor":"Hotel/DMC direct or Fora","tier":"ultra"},{"name":"Inkaterra Machu Picchu Pueblo Hotel","why_ultra":"Relais & Châteaux, 85 rooms, private 5-ha cloud-forest reserve at 2,450 m","earning":"R&C/Inkaterra commission via Fora/Virtuoso","virtuoso_value_add":"Nature/conservation programming + R&C amenities","mor":"Hotel/DMC direct or Fora","tier":"luxury"},{"name":"Sumaq Machu Picchu Hotel","why_ultra":"Culinary-forward luxury: tasting menus, pisco/cooking workshops, Andean ceremonies","earning":"Hotel commission via Fora/OutsideAgents","virtuoso_value_add":"Pre-loaded chef + cultural experiences","mor":"Hotel/DMC direct or Fora","tier":"premier–luxury"},{"name":"Belmond Hiram Bingham (rail)","why_ultra":"World''s most storied luxury train to the Wonder; bundles entry + bus + guide + dining","earning":"Belmond/PeruRail commission via Fora/Virtuoso","virtuoso_value_add":"Bundled citadel access removes the ticket-scramble","mor":"Belmond/PeruRail","tier":"ultra"}],"source_verified":"2026-07-07","hero":{"query":"Machu Picchu, Peru"},"geo":{"lat":-13.1631,"lng":-72.545}}'::jsonb, 0),
