  ('cartagena-colombia', '10S', 'Cartagena & Colombia''s Caribbean Coast', 'Colombia', 'Walled colonial casas and Caribbean nights', 'live', 'verified', 'venice', 'Colombia''s Caribbean Coast', '{"romance","tropical","culture"}', '{"tropical"}', '{"essential","premier","luxury","ultra"}', null, null, '{"key_facts":["Cartagena''s Ciudad Amurallada (walled old city + fortifications) is the anchor; Castillo San Felipe is the largest Spanish fort in South America; most visitors need 3–4 days.","Islas del Rosario + Barú (Playa Blanca) — ~1hr speedboat to Corales del Rosario National Park, reef snorkel, beach lunch.","Getsemaní — best street art on the coast + Plaza de la Trinidad salsa nights, just outside the walls.","Santa Marta + Tayrona NP protect 150 km² where the Sierra Nevada meets the sea; Cabo San Juan is the iconic cove.","Barranquilla Carnival — UNESCO Intangible Heritage, largest carnival outside Brazil; 2026 dates 14–17 February."],"safety":{"emergency":"123","hospital":"Cartagena private hospitals (stabilization); serious cases route to Bogotá or US medical evacuation","book_enabled":true,"bin":"BOOK WITH WARNING","risk_codes":["C","T","U","K","N"],"risk_code_meanings":{"C":"Crime — violent crime (murder, assault, robbery), drugging (scopolamine), extortion, express kidnapping occur throughout Colombia incl. cities","T":"Terrorism — attacks possible with little/no warning; car bombs, grenades, IEDs, drones","U":"Unrest — demonstrations can shut roads and turn violent","K":"Kidnapping or Hostage-Taking — kidnapping-for-ransom reported","N":"Natural Disaster — volcano, earthquake, landslide"},"named_danger":["Arauca","Cauca excl Popayán","Valle del Cauca excl Cali","Norte de Santander","Venezuela border ~10km"],"cartagena_in_named_danger":false,"air_access_verified":"CTG (Rafael Núñez Intl) — direct international incl. Miami (AA, Avianca) and New York JFK (JetBlue year-round, Avianca seasonal)","water":"bottled","vaccinations":"yellow fever recommended for Tayrona/jungle/Sierra Nevada; dengue present on coast; check CDC","scopolamine_caution":"''devil''s breath''/burundanga drugging — colourless/tasteless; never accept drinks/food/tabs from strangers; dating-app method documented in Cartagena"},"timing":{"peak":"Dec–Mar/Apr (dry); true peak mid-Dec → mid/late-Jan","inflection_curve_start":"early December","fire_date":"mid-to-late November (peak); ~late-January (Barranquilla Carnival)","event_peaks":[{"event":"Barranquilla Carnival","dates_2026":"14–17 February","note":"UNESCO; largest carnival outside Brazil; Barranquilla rooms sell out/price hard"},{"event":"Independence Day (Cartagena)","dates":"November 11","note":"coastal rates +30–40% Nov 9–12"},{"event":"Christmas–New Year","dates":"Dec 20–31","note":"maximum annual congestion"}],"off_season_fill":"Aug–Nov (rates ~half of peak); Jul–Aug veranillo del Niño = best weather-to-cost"},"jewels":[{"name":"Walled Old City + rampart sunset (Café del Mar)","si_tag":"romance","tier":"premier","source":"https://www.lonelyplanet.com/articles/top-things-to-do-in-cartagena-colombia","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"cobbled lanes, Plaza Santo Domingo, and a sunset walk on the coral-stone ramparts","si":"romance","blurb":"cobbled lanes, Plaza Santo Domingo, and a sunset walk on the coral-stone ramparts","when":"Dec–Mar/Apr","commission":"hotel + city-tour affiliate; wedding via DMC/villa"},{"name":"Walled-city colonial-mansion buyout wedding","si_tag":"romance","tier":"premier","source":"https://cartagenadreams.com/explore-cartagena/old-city/unesco-walled-city-colonial-mansion-rental-groups-your-complete-guide-to-cartagena/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"take over a restored 17th–18th-c. casa for ceremony + dinners + party","si":"romance","blurb":"take over a restored 17th–18th-c. casa for ceremony + dinners + party","when":"Dec–Mar/Apr","commission":"MoR villa + wedding DMC ~10–20% land"},{"name":"Rosario private-island wedding (yacht/speedboat)","si_tag":"romance","tier":"ultra","source":"https://two.travel/planning-your-wedding-in-cartagena-colombia/","si":"romance","commission":"DMC + island villa MoR"},{"name":"Islas del Rosario + Barú (Playa Blanca)","si_tag":"tropical","tier":"essential","source":"https://www.getyourguide.com/cartagena-l362/cartagena-rosario-islands-and-playa-blanca-excursion-with-snorkeling-or-aquarium-t934710/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"reef snorkel in Corales del Rosario NP, beach-club lunch, hammocks on Playa Blanca","si":"tropical","blurb":"reef snorkel in Corales del Rosario NP, beach-club lunch, hammocks on Playa Blanca","when":"Dec–Mar/Apr","commission":"GetYourGuide/Viator affiliate; island villa MoR"},{"name":"Cabo San Juan, Tayrona NP","si_tag":"tropical","tier":"essential","source":"https://mytriptocolombia.com/visit-parc-tayrona/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"Dec–Mar/Apr","commission":"Santa Marta DMC + park fee pass-through"},{"name":"Palomino river-tube + beach","si_tag":"tropical","tier":"essential","source":"https://smallgirlbigbackpack.com/how-to-get-to-tayrona-national-park/","si":"tropical","commission":"coast DMC + boutique-lodge affiliate"},{"name":"Getsemaní (street art, Plaza de la Trinidad, Café Havana)","si_tag":"culture","tier":"essential","source":"https://www.cartagenaexplorer.com/getsemani-guide/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"walking-tour affiliate + boutique lodging"},{"name":"Castillo San Felipe de Barajas","si_tag":"culture","tier":"essential","source":"https://mycartagenatrip.com/things-to-do-in-cartagena/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the largest Spanish fort in South America, on a hill over the city","si":"culture","blurb":"the largest Spanish fort in South America, on a hill over the city","when":"Dec–Mar/Apr","commission":"city-tour affiliate"},{"name":"Minca (coffee/cloud forest, Sierra Nevada)","si_tag":"culture","tier":"essential","source":"https://mytriptocolombia.com/visit-parc-tayrona/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dec–Mar/Apr","commission":"Santa Marta DMC + eco-lodge affiliate"},{"name":"Ciudad Perdida (Teyuna) 4-day trek","si_tag":"culture","tier":"premier","source":"https://www.kimkim.com/c/the-lost-city-tayrona-park-adventure-10-days","hook":"4-day guided-only trek to pre-Columbian ruins in the Sierra Nevada","si":"culture","blurb":"4-day guided-only trek to pre-Columbian ruins in the Sierra Nevada","commission":"licensed-operator DMC (mandatory)"},{"name":"Barranquilla Carnival","si_tag":"culture","tier":"premier","source":"https://ich.unesco.org/en/RL/carnival-of-barranquilla-00051","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"UNESCO Masterpiece of Intangible Heritage, largest carnival outside Brazil; 2026 dates 14–17 Feb","si":"culture","blurb":"UNESCO Masterpiece of Intangible Heritage, largest carnival outside Brazil; 2026 dates 14–17 Feb","when":"Dec–Mar/Apr","commission":"event DMC + Barranquilla hotel affiliate (fire ~late-Jan)"},{"name":"Mompox (UNESCO colonial river town)","si_tag":"culture","tier":"premier","source":"https://en.wikipedia.org/wiki/Barranquilla_Carnival","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dec–Mar/Apr","commission":"specialist heritage DMC + boutique lodging"}],"faq":[{"q":"How much does a walled-city wedding in Cartagena cost?","a":"A private-villa wedding for 40–60 guests starts around USD $40,000, including a 2–3-night buyout of a restored colonial casa with pool, rooftop, chef, butler and security. Cartagena''s wedding DMCs assemble venue, villa, catering and logistics as the agent-of-record (~10–20% land).","source":"cartagenadreams.com, 2026-07-07","si_tag":"romance"},{"q":"How do you get to the Rosario Islands and Playa Blanca from Cartagena?","a":"By speedboat — about 1 hour offshore to the Corales del Rosario y San Bernardo National Park for reef snorkeling and a beach-club lunch on Playa Blanca (Barú). Book a licensed day-tour; the ~1-hr open-water return chops up in the windy Dec–Apr season, so tours often head back earlier.","source":"tomplanmytrip.com, 2026-07-07","si_tag":"tropical"},{"q":"What are the must-do sights in Cartagena?","a":"The walled Ciudad Amurallada is the anchor — most visitors need 3–4 days — with Castillo San Felipe de Barajas, the largest Spanish fort in South America, and Getsemaní''s street art and Plaza de la Trinidad salsa nights just outside the walls.","source":"mycartagenatrip.com, 2026-07-07","si_tag":"culture"},{"q":"What''s the real risk to plan for in Cartagena?","a":"Scopolamine (\"devil''s breath\") drugging is the headline traveler risk — colourless and tasteless, slipped into drinks or offered items to incapacitate and rob. The US Embassy singled out Cartagena (with Medellín and Bogotá) as a hotspot, often via dating apps. Never accept drinks, food or tabs from strangers, and travel during daylight.","source":"financecolombia.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Cartagena & Colombia''s Caribbean Coast — Walled-City Weddings, Rosario Islands & Tayrona | TravelWell.World","jsonld_type":"TouristDestination","freshness":"2026-07-07","search_language":"es-CO","long_tail_en":["things to do in Cartagena Colombia","Cartagena walled city weddings","Rosario Islands day trip from Cartagena","Tayrona National Park Cabo San Juan guide","is Cartagena safe 2026","Cartagena luxury colonial hotels"],"local_keywords":["qué hacer en Cartagena","Islas del Rosario tour","Ciudad Amurallada Cartagena","bodas Cartagena","Parque Tayrona Cabo San Juan","hoteles de lujo Cartagena"],"hreflang":["en","es-CO"]},"booking":null,"si_checklist_25":null,"sis_present":["romance","tropical","culture"],"ultra":[{"name":"Sofitel Legend Santa Clara","type":"17th-c. former monastery, walled city — prestige address","routing":"Fora/Virtuoso preferred","tier":"ultra"},{"name":"Casa Pestagua","type":"18th-c. palace, Relais & Châteaux, Two MICHELIN Keys 2025","routing":"Fora/Virtuoso preferred","tier":"ultra"},{"name":"Casa San Agustín","type":"11-key colonial mansion, Leading Hotels of the World","routing":"Fora/Virtuoso preferred","tier":"ultra"},{"name":"Hotel Charleston Santa Teresa","type":"grande-dame walled-city luxury","routing":"preferred-partner + host","tier":"luxury→ultra"},{"name":"Tcherassi Hotel + Spa","type":"designer boutique, restored colonial house","routing":"preferred-partner + host","tier":"luxury"},{"name":"Blue Apple Beach (Barú)","type":"design beach club + villa, Barú island","routing":"villa/MoR + host","tier":"ultra"},{"name":"Walled-city private villas","type":"full colonial-house buyouts, chef/butler/security","routing":"MoR villa + wedding DMC","tier":"ultra"}],"source_verified":null,"hero":{"query":"Cartagena & Colombia''s Caribbean Coast, Colombia"},"geo":{"lat":10.391,"lng":-75.4794}}'::jsonb, 2),
  ('akumal-mexico', '10S', 'Akumal', 'Mexico', 'Turtle bay, cenotes and reef', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"diveglobal","ocean","culture"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":["Akumal means ''place of the turtles'' in Maya; the bay''s seagrass beds feed wild green sea turtles.","A certified guide and life jacket are mandatory to enter the turtle-snorkel area.","No touching turtles (federal offense); keep 3 m distance, 2 min per turtle, biodegradable sunscreen or rashguard only.","Turtle sightings permitted 8am-5pm; sessions cap at ~55 minutes; no fins, no diving on the circuit.","Cenote and reef diving are easily reached, making Akumal a serene dive base."],"safety":{"emergency":"911","hospital":"Nearest trauma: Hospiten Riviera Maya, Playa del Carmen (+52 984 159 2200), ~25 min north; local clinics stabilize/transfer; major trauma to Cancún","advisory_level":"L2","malaria":"none in tourist Quintana Roo","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dec-Apr (dry season; highest rates, biggest crowds)","shoulder":"May-Jun & Nov (~30-40% off, good weather)","green":"Jun-mid-Oct (hurricane/low; cheapest)","turtle_season":"green turtles graze year-round; snorkel 8am-5pm, <=55-min sessions; nesting ~May-Oct overlaps green/sargassum months","sargassum_window":"Apr-Aug (Jun-Jul peak); Akumal affected (seagrass bay, naturally weedy)","booking_window_lead_time":"peak 3-4 months (villa stock finite, book earlier); shoulder 4-6 months","holiday_event_peaks":["Christmas/New Year","Spring Break (Mar)","Semana Santa"],"fill_the_beds":"sargassum/green months lead with Yal-Ku Lagoon, cenote dives, reef dives, Tulum-ruin loops, turtle morning at opening","campaign_start_trigger":"peak campaigns open Aug-Sep; shoulder ~3-4 months out; turtle-nesting off-peak push into green season"},"jewels":[{"name":"Guided Akumal Bay turtle snorkel","si_tag":"Ocean Adventures","status":"future","tier":"essential","hook":"Certified-guide snorkel over seagrass to see wild green turtles — no touch, low impact.","bookable_category":"guided snorkel tour","source":"https://absolute-adventure-mexico.com/snorkeling/akumal-bay-regulation-swim-with-the-turtles/","si":"ocean","blurb":"Certified-guide snorkel over seagrass to see wild green turtles — no touch, low impact.","commission":"Amstar 12% / affiliate; bay + guide fees pass-through"},{"name":"Yal-Ku Lagoon snorkel","si_tag":"Ocean Adventures","status":"future","tier":"essential","hook":"Calm brackish lagoon where cenote freshwater meets the sea, rich in fish.","bookable_category":"snorkel add-on","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","si":"ocean","blurb":"Calm brackish lagoon where cenote freshwater meets the sea, rich in fish.","commission":"affiliate 4-8%; entry pass-through"},{"name":"Akumal-area cenote cavern dive","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Guided cavern dives inland pair the turtle bay with cave country.","bookable_category":"cenote cavern dive (guide required)","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Guided cavern dives inland pair the turtle bay with cave country.","when":"Dec-Apr","commission":"DMC 12% / affiliate 4-8%"},{"name":"Akumal reef dive","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Shallow near-shore reef dives with easy multi-dive days.","bookable_category":"reef dive","source":"https://www.prodiveinternational.com/diving/mexico/puerto-aventuras/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Shallow near-shore reef dives with easy multi-dive days.","when":"Dec-Apr","commission":"dive-operator affiliate / DMC 12%"},{"name":"Tulum ruins + turtle-bay combo day","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Cliff-top Maya ruins paired with an Akumal turtle morning.","bookable_category":"guided combo excursion","source":"https://www.embracethejourneytravel.com/agent-portal/vendor-list/amstar/","si":"culture","blurb":"Cliff-top Maya ruins paired with an Akumal turtle morning.","commission":"Amstar 12%; ruin/bay entry pass-through"}],"faq":[{"q":"What''s the real risk to plan for in Akumal?","a":"Sargassum, water, mosquitoes and hurricanes — not violent crime. 2026 is tracking a record sargassum year, with Akumal affected Apr–Aug (Jun–Jul peak) because the bay is seagrass habitat and naturally weedy by design; drink bottled/purified water only, use repellent for dengue (peak May–November, no malaria), and note hurricane season runs June–November.","source":"deeparrival.com / cdc.gov, 2026-07-04","si_tag":"safety"},{"q":"Can you swim with wild sea turtles in Akumal, and when''s best?","a":"Yes — it is the whole reason to come, and green turtles graze the bay''s seagrass year-round. Go at 8am opening for the calmest water and fewest boats; snorkeling is permitted only 8am–5pm in sessions capped at ~55 minutes, always with a certified guide over the seagrass beds.","source":"absolute-adventure-mexico.com, 2026-07-04","si_tag":"ocean"},{"q":"Can I dive cenotes and reef from Akumal?","a":"Yes — Akumal makes a serene dive base for both. Guided cenote cavern dives sit just inland (Cenote Azul corridor) and shallow reef dives are close to shore; cavern diving requires a certified cave/cavern guide and stays in the daylight zone. Observe no-fly of 18h single / 24h repetitive; the nearest chamber is ~25 min north in Playa del Carmen.","source":"sssnetwork.com / alohawanderers.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Is Akumal good for a honeymoon?","a":"Yes, if you want quiet and private over resort buzz. Akumal is villa-driven — beachfront villas with private pools and chef service, plus the wider luxury tier at ~US$400–600+/night in March — and it is calmer and more purposeful than Playa or Tulum. For branded ultra, Rosewood/Banyan Tree at Mayakoba sit ~35–40 min north with an easy turtle-morning day trip.","source":"machupicchu.org / rentalescapes.com, 2026-07-04","si_tag":"romance"},{"q":"When is the best time to visit Akumal, and when is it cheapest?","a":"Nov–March is the best weather window; the cheapest is the green season, June–mid-October. Peak Dec–Apr brings the best conditions and highest rates; May–June and November shoulders run ~30–40% off with thinner crowds; the green season is hot, rainy and cheapest but carries hurricane exposure (Jun–Nov).","source":"machupicchu.org / travelswithelle.com, 2026-07-04","si_tag":"tropical"},{"q":"Can I visit Maya ruins from Akumal?","a":"Yes — Akumal pairs a turtle morning with cliff-top Maya ruins in a single day. Tulum''s ruins are a short drive south and Cobá is inland; a common loop is ruins at 8–10am then the turtle bay after, bookable as a guided combo excursion.","source":"embracethejourneytravel.com, 2026-07-04","si_tag":"culture"}],"seo":{"meta_title":"Akumal Travel Guide 2026 — Swim with Sea Turtles Responsibly | TravelWell.World","meta_description":"Plan Akumal, ''place of the turtles'': guided no-touch turtle snorkeling rules, cenote & reef diving, straight 2026 sargassum, Level 2 safety and nearest dive-chamber contacts.","slug":"akumal-mexico","jsonld_type":"TouristDestination","content_freshness":"2026-07-04","search_language":["en","es-MX"],"local_keywords":["nadar con tortugas en Akumal","reglas nadar con tortugas Akumal 2026","snorkel en Akumal","buceo en cenotes Akumal","mejor época para ver tortugas en Akumal","sargazo Akumal 2026","Laguna Yal-Ku Akumal","villas frente al mar Akumal"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"diveglobal","status":"future"},{"si":"ocean","status":"future"},{"si":"culture","status":"future"}],"ultra":[{"name":"Akumal beachfront luxury villas","price_tier":"ultra","virtuoso":false,"earning":"on application / host or luxury-DMC villa AOR","mor_posture":true,"note":"no branded ultra hotel in-village; top villa tier","source":"https://www.rentalescapes.com/rentals/luxury-vacation-rentals-mexico/riviera-maya/akumal"},{"name":"Rosewood Mayakoba (~35-40 min north)","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"note":"nearest true ultra hotel","source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Banyan Tree / Andaz-Alila Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"La Casa de la Playa (Grupo Xcaret)","price_tier":"ultra","virtuoso":true,"earning":"15% via Xcaret Agents Pro OR host-Virtuoso ($100 credit)","mor_posture":true,"source":"https://www.virtuoso.com/hotels/16561922/la-casa-de-la-playa"}],"source_verified":"2026-07-04","hero":{"query":"Akumal, Mexico"},"geo":{"lat":20.3958,"lng":-87.3153}}'::jsonb, 3),
  ('ambergris-caye-belize', '10S', 'Ambergris Caye / San Pedro', 'Belize', 'Ambergris Caye Belize', 'live', 'verified', 'tropicalBeach', 'Belize', '{"tropical","liveaboard","romance","expedition"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Belize''s largest island and #1 tourism engine; runs parallel to the UNESCO Belize Barrier Reef, ~35 mi NE of Belize City.","Hol Chan Marine Reserve (est. 1987, ~4 mi south of San Pedro) protects ~18 km2 with 160+ fish species; Shark Ray Alley added 1999.","Belize''s national recompression capability is on-island: SSS hyperbaric chamber (since 1989) + DAN-affiliated Belize Chamber Project (2015), both 24/7.","Air access via BZE Philip Goldson Intl -> SPR San Pedro, ~20-min puddle-jumper (Tropic Air / Maya Island Air) or ~90-min water taxi via Caye Caulker.","English is Belize''s official language - the only English-official nation in Central America."],"safety":{"emergency":"911 (also 90); San Pedro Police 206-2022; San Pedro Coast Guard 222-5260","hyperbaric_chamber":"YES - on Ambergris/San Pedro: SSS Belize Hyperbaric Facility (est. 1989, 4-diver lock, US Navy tables, 24/7) + DAN-affiliated Belize Chamber Project (2015). National dive-safety asset.","hospital":"Lighthouse Medical Center (San Pedro, private) for urgent care; serious trauma -> Karl Heusner Memorial Hospital (KHMH), Belize City - the only trauma centre in Belize; then US evac. Island remoteness flagged.","book_enabled":true,"l3_disclosure":true,"state_dept_carveout":"cayes/San Pedro open; only Southside Belize City (Haulover Creek Canal to Fabers Road) restricted","stay_in_zone":true,"air_access_verified":true,"malaria":"none on the cayes; Belize WHO-certified malaria-free 2023; small mainland Cayo District cluster (Apr 2025) - mainland only","water":"do not drink tap water on the cayes; use bottled/filtered","mosquito_borne":"dengue primary concern; also chikungunya, Zika (day-biting Aedes) - use repellent"},"timing":{"inflection_curve_start":"2026-12-20","peak":"late-Dec through April (dry season); dive peak extends to June","fire_date":"2026-12-08","fire_date_secondary":"2026-11-01 (Mar-Apr dive/whale-shark surge, 4-6 mo lead)","shoulder":"September-November (wet/green season, lower rates)","green":"September-November","booking_lead":"4-6 months (dive/liveaboard/atoll + ultra private-island)","off_season_specials":"green-season weekly/monthly villa & condo discounts","event_peaks":["San Pedro Lobster Festival (early summer; 2026 advertised Jul 1-12)","Costa Maya Festival (August; 2026 dates unverified)"],"whale_shark_window":"Mar-Jun full-moon (2026 full moons Mar 14, Apr 13); Apr-May best"},"jewels":[{"name":"Hol Chan Marine Reserve (Zone A)","si_tag":"Dive Liveaboards / Reef Diving","status":"live","hook":"Signature 30-ft dive/snorkel; moray, turtles, 160+ fish species in a protected channel.","bookable_category":"guided dive/snorkel","tier":"comfort","source":"https://en.wikipedia.org/wiki/Hol_Chan_Marine_Reserve + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards / Reef Diving","blurb":"Signature 30-ft dive/snorkel; moray, turtles, 160+ fish species in a protected channel.","when":"late-Dec through April","commission":"David CLIA dive lane","accessed":"2026-07-06"},{"name":"Shark Ray Alley (Zone D)","si_tag":"Dive Liveaboards / Reef Diving","status":"live","hook":"Guided shallow encounter with docile nurse sharks and southern stingrays.","bookable_category":"guided snorkel/dive","tier":"comfort","source":"https://ambergrisdivers.com/trip/snorkeling-hol-chan-shark-ray-alley-marine-reserve/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards / Reef Diving","blurb":"Guided shallow encounter with docile nurse sharks and southern stingrays.","when":"late-Dec through April","commission":"David CLIA dive lane","accessed":"2026-07-06"},{"name":"Mexico Rocks & Tres Cocos","si_tag":"Dive Liveaboards / Reef Diving","status":"live","hook":"Shallow patch-reef gardens north of town; ideal for new divers and long snorkels.","bookable_category":"guided dive/snorkel","tier":"comfort","source":"https://www.backpackerswanderlust.com/diving-in-ambergris-caye-belize/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards / Reef Diving","blurb":"Shallow patch-reef gardens north of town; ideal for new divers and long snorkels.","when":"late-Dec through April","commission":"David CLIA dive lane","accessed":"2026-07-06"},{"name":"Great Blue Hole + Lighthouse Reef","si_tag":"Dive Liveaboards / Reef Diving","status":"live","hook":"Bucket-list 410-ft UNESCO sinkhole; full-day boat or scenic-flight-and-dive combo.","bookable_category":"dive expedition / air combo","tier":"premier","source":"https://ambergrisdivers.com/trip/great-blue-hole-dive-and-lighthouse-reef-day-tour/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards / Reef Diving","blurb":"Bucket-list 410-ft UNESCO sinkhole; full-day boat or scenic-flight-and-dive combo.","when":"late-Dec through April","commission":"David CLIA dive lane + air affiliate","accessed":"2026-07-06"},{"name":"Bacalar Chico National Park & Marine Reserve","si_tag":"Dive Liveaboards / Reef Diving","status":"live","hook":"Remote far-north reef, mangrove and Maya-history diving near the Mexico border.","bookable_category":"dive expedition / private charter","tier":"premier","source":"https://www.viaventure.com/destinations/belize/ambergris-caye/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards / Reef Diving","blurb":"Remote far-north reef, mangrove and Maya-history diving near the Mexico border.","when":"late-Dec through April","commission":"David CLIA dive lane","accessed":"2026-07-06"},{"name":"Grand Slam fly-fishing (bonefish + permit + tarpon)","si_tag":"GEA","status":"live","hook":"400+ sq mi of flats; El Pescador Orvis-endorsed base; all three species in a day.","bookable_category":"lodge / guided angling","tier":"luxury","source":"https://www.elpescador.com/articles/from-bonefish-to-tarpon-the-anglers-guide-to-el-pescadors-grand-slam/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"400+ sq mi of flats; El Pescador Orvis-endorsed base; all three species in a day.","when":"late-Dec through April","commission":"CLIA + Fora (lodge/villa)","accessed":"2026-07-06"},{"name":"Gladden Spit whale-shark encounter","si_tag":"GEA","status":"live","hook":"Mar-Jun full-moon aggregation; snorkel/dive with whale sharks (mainland-launched marquee day-add).","bookable_category":"guided dive/snorkel","tier":"premier","source":"https://belizescuba.com/diving-snorkeling/whale-sharks/ + Accessed 2026-07-06","si":"expedition","blurb":"Mar-Jun full-moon aggregation; snorkel/dive with whale sharks (mainland-launched marquee day-add).","commission":"David CLIA dive lane","accessed":"2026-07-06"},{"name":"Caye Caulker day trip","si_tag":"GEA","status":"live","hook":"Car-free ''go slow'' sister island 30 min by boat; the Split, cheaper eats.","bookable_category":"day tour / water taxi","tier":"essential","source":"https://www.viaventure.com/destinations/belize/ambergris-caye/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Car-free ''go slow'' sister island 30 min by boat; the Split, cheaper eats.","when":"late-Dec through April","commission":"tour affiliate (Viator) + water taxi","accessed":"2026-07-06"},{"name":"Secret Beach (west side)","si_tag":"Tropical Islands / Beaches","status":"live","hook":"Famous shallow-lagoon bar-and-beach scene; golf-cart destination, calm swim water.","bookable_category":"day trip / F&B","tier":"comfort","source":"https://agentsgather.com/vacation-rentals-ambergris-caye-belize/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Tropical Islands / Beaches","blurb":"Famous shallow-lagoon bar-and-beach scene; golf-cart destination, calm swim water.","when":"late-Dec through April","commission":"tour + F&B affiliate","accessed":"2026-07-06"},{"name":"San Pedro town + Belikin nightlife","si_tag":"Tropical Islands / Beaches","status":"live","hook":"Sand-street town core, dockside bars, live music, Lobster Festival hub.","bookable_category":"F&B / event","tier":"essential","source":"https://www.thephoenixbelize.com/explore-more/ultimate-guide-belize-lobster-season-san-pedro + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Tropical Islands / Beaches","blurb":"Sand-street town core, dockside bars, live music, Lobster Festival hub.","when":"late-Dec through April","commission":"F&B / event affiliate","accessed":"2026-07-06"},{"name":"Sunset sail / private charter","si_tag":"Romance & Honeymoons","status":"live","hook":"Champagne catamaran sail over the reef lagoon; the honeymoon signature.","bookable_category":"charter / activity","tier":"premier","source":"https://www.viaventure.com/destinations/belize/ambergris-caye/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Champagne catamaran sail over the reef lagoon; the honeymoon signature.","when":"late-Dec through April","commission":"Fora / activity affiliate","accessed":"2026-07-06"}],"faq":[{"q":"What is the best diving and snorkeling on Ambergris Caye?","a":"Start at Hol Chan Marine Reserve and Shark Ray Alley. The signature ~30-ft channel dive delivers moray, turtles and 160+ fish species, while Shark Ray Alley — added as Zone D in 1999 — puts you in shallow water with docile 4–6 ft nurse sharks and southern stingrays. Both are guided, beginner-friendly profiles because they are shallow and protected.","source":"en.wikipedia.org, 2026-07-06","si_tag":"liveaboard"},{"q":"Do you need a car on Ambergris Caye?","a":"No — the island runs on golf carts, not cars, and beachfront San Pedro properties sit a 10-minute walk from the airstrip and steps from the water-taxi dock. English is the official language (Belize is the only English-official nation in Central America), so North American travelers move through town with zero language friction.","source":"agentsgather.com, 2026-07-06","si_tag":"tropical"},{"q":"Where should you stay for a honeymoon on Ambergris Caye?","a":"For seclusion, Cayo Espanto is a private island 3 miles off San Pedro with 7 all-inclusive villas and an 18-guest cap from ~US$1,695/villa/night; for adults-only boutique romance, Matachica offers thatched casitas. Both read romance-forward because the property caps guest count and builds the stay around couples.","source":"aprivateisland.com, 2026-07-06","si_tag":"romance"},{"q":"Can you fish the Grand Slam from Ambergris Caye?","a":"Yes — Ambergris fronts 400+ sq mi of flats, channels and lagoons where bonefish, permit and tarpon can all be landed in one day, with El Pescador the Orvis-endorsed base for 50+ years. Tarpon peaks July–September; bonefish and permit run year-round, so the slam is a realistic single-day target.","source":"elpescador.com, 2026-07-06","si_tag":"expedition"},{"q":"What''s the real risk to plan for on Ambergris Caye?","a":"Island remoteness for serious medical events, not crime. San Pedro''s Lighthouse Medical Center handles urgent care, but serious trauma routes to Karl Heusner Memorial Hospital in Belize City — the only trauma centre in Belize — then to the US, requiring air/water transfer off the island. Dengue is the primary mosquito-borne concern; there is no malaria on the cayes (Belize was WHO-certified malaria-free in 2023).","source":"belizetravelinsider.com, 2026-07-06","si_tag":"safety"},{"q":"Is diving the Great Blue Hole dangerous?","a":"It is an advanced dive, not a beginner novelty. The Blue Hole bottoms below recreational limits (~410 ft total); recreational dives target ~130 ft along the stalactite ledges, so treat it as advanced/technical-adjacent with sound gas planning. The offshore boat crossing is 2.5–3 hours each way, or ~20 minutes by scenic flight from San Pedro.","source":"ambergriscaye.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Ambergris Caye & San Pedro, Belize: Dive the Reef, Stay Well | TravelWell.World","meta_description":"Belize''s #1 island — dive Hol Chan and Shark Ray Alley, honeymoon at Cayo Espanto or Matachica, chase the Grand Slam on the flats. National hyperbaric chamber on-island. TravelWell.","slug":"ambergris-caye-belize","primary_keyword":"Ambergris Caye Belize","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":"en","local_keywords":["Ambergris Caye Belize","San Pedro Belize diving","Hol Chan Marine Reserve snorkel","Ambergris Caye honeymoon resort","Cayo Espanto private island Belize","Belize barrier reef diving","Ambergris Caye villa rental","Shark Ray Alley tour","Belize Grand Slam fly fishing","Great Blue Hole day trip San Pedro"],"hreflang":["en"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"Dive Liveaboards / Reef Diving","status":"live"},{"si":"romance","status":"live"},{"si":"expedition","status":"live"}],"ultra":[{"name":"Cayo Espanto","why_ultra":"Private-island, 7 all-inclusive seafront villas incl. overwater Casa Ventanas, 18-guest cap, 24-hr dedicated houseman, chef-tailored meals, whole-island buyout.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"resort credit / arrival amenity / upgrade on availability where consortia-eligible (confirm preferred status)","mor":"commissionable AOR (not merchant)","tier":"ultra"},{"name":"Victoria House Resort & Spa","why_ultra":"Five-star colonial-Caribbean flagship, spa, personalized service; ranks with the island''s top hotels.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"consortia amenity where eligible","mor":"commissionable AOR","tier":"luxury"},{"name":"Matachica Resort & Spa","why_ultra":"Adults-only boutique, private thatched casitas, romance-forward.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"consortia amenity where eligible","mor":"commissionable AOR","tier":"luxury"},{"name":"Las Terrazas","why_ultra":"Design-led north-shore residences, full kitchens, sea-view balconies.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"consortia amenity where eligible","mor":"commissionable AOR","tier":"luxury"}],"source_verified":"2026-07-06","hero":{"query":"Ambergris Caye / San Pedro, Belize"},"geo":{"lat":17.9214,"lng":-87.9611}}'::jsonb, 4),
  ('antigua-guatemala', '10S', 'Antigua', 'Guatemala', 'Colonial streets under two volcanoes', 'live', 'verified', 'kyoto', 'Guatemala', '{"expedition","culture","culinary","wildlife"}', '{}', '{"essential","comfort","premier","luxury"}', null, null, '{"key_facts":["UNESCO World Heritage colonial city (16th-18th c. Spanish architecture) cradled beneath Volcanoes Agua, Fuego and Acatenango.","Base for the Acatenango overnight trek (summit 3,976 m) with front-row views of continuously erupting Fuego; Pacaya (2,552 m) is the gentler guided lava hike.","Semana Santa is the most famous Holy Week in the Americas - dawn processions over colored-sawdust alfombras; books ~1 year ahead on tiny inventory.","Premier coffee origin: Finca Filadelfia (est. 1870) and nonprofit De la Gente run finca-to-cup tours minutes from the plaza.","A rising colonial-wedding and honeymoon destination anchored by converted-palace boutique hotels (Casa Santo Domingo, Palacio de Dona Leonor, Pensativo House)."],"safety":{"emergency":"110 police (PNC) / 122-123 bomberos (fire-rescue) / 128 Cruz Roja ambulance / 1500 PROATUR tourist assistance; Antigua POLITUR tourist police","hospital":"Hospital Nacional Pedro de Bethancourt (Antigua) + private clinics for stabilization; major trauma/evac to Guatemala City ~1 hr","book_enabled":true,"l3_disclosure":true,"state_dept_carveout":"Antigua/Sacatepequez explicitly cleared; avoid San Marcos/Huehuetenango/Zone-18/Villa Nueva","stay_in_zone":true,"air_access_verified":true,"altitude":"Antigua ~1,500 m (mild); Acatenango summit 3,976 m = serious AMS; Pacaya ~2,552 m","water":"bottled/purified only","malaria":"no malaria risk in Antigua (highland); dengue/Zika precaution advised"},"timing":{"inflection_curve_start":"peak dry season Nov-Mar (baseline); Feb is the sweet spot (crowds dip, dry)","peak":"Semana Santa (Holy Week) late Mar/early Apr - THE event; 2027 ~Mar 24-28 (Good Friday Mar 26)","fire_date":"general dry-season curve: fire ~mid-October (curve-start -1-2 wks); Semana Santa 2027: fire ~Apr-May 2026 (~1 yr ahead), last-call ''book by January''","shoulder":"late Oct-Nov & Feb (dry, thinner crowds, easier rates)","green":"May-Oct wet season (lower rates; Sep-Oct wettest but quietest/cheapest)","booking_lead":"Semana Santa ~1 year; weddings 9-12 months; general dry-season 2-3 months","off_season_specials":"wet-months ''quiet Antigua'' value: coffee-finca/roasting tours, jade & textile workshops, cooking classes, Casa Santo Domingo museums + spa, guided treks with flexible dates","event_peaks":["Semana Santa (late Mar/early Apr)","Sumpango Barriletes Gigantes giant-kite festival (Nov 1, All Saints)","Christmas/New Year"]},"jewels":[{"name":"Acatenango sunrise-over-Fuego overnight","si_tag":"Global Expedition Adventures","status":"live","hook":"Guided overnight ridge camp at ~3,500 m watching Fuego erupt through the night and sunrise over the highlands.","bookable_category":"guided overnight trek (guided-only)","tier":"premier","source":"https://www.muchbetteradventures.com/magazine/acatenango-volcano-hike-guide/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Guided overnight ridge camp at ~3,500 m watching Fuego erupt through the night and sunrise over the highlands.","when":"Semana Santa  late Mar/early Apr","commission":"DMC 10-12% / Viator-GetYourGuide 4-8%; park + guide fees pass-through"},{"name":"Pacaya lava hike + marshmallows","si_tag":"Global Expedition Adventures","status":"live","hook":"Shorter guided hike to warm volcanic ground near active Pacaya; family-friendly acclimatizer.","bookable_category":"guided day hike","tier":"essential","source":"https://theworldtravelguy.com/acatenango-hike-volcan-de-fuego/","si":"expedition","blurb":"Shorter guided hike to warm volcanic ground near active Pacaya; family-friendly acclimatizer.","commission":"affiliate 4-8% / DMC 10-12%; park fee pass-through"},{"name":"Semana Santa alfombras + processions","si_tag":"Culture & Heritage","status":"future","hook":"Dawn Good Friday La Merced procession over street carpets of colored sawdust and flowers - the most famous Holy Week in the Americas.","bookable_category":"event + hotel/DMC room block","tier":"premier","source":"https://livinginguatemala.com/events/semana-santa-guatemala/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Dawn Good Friday La Merced procession over street carpets of colored sawdust and flowers - the most famous Holy Week in the Americas.","when":"Semana Santa  late Mar/early Apr","commission":"hotel/DMC AOR; event pass-through; book ~1 yr ahead"},{"name":"Cerro de la Cruz viewpoint","si_tag":"Culture & Heritage","status":"future","hook":"Hilltop cross with the classic Antigua panorama framed by Volcan Agua.","bookable_category":"free / guided city tour","tier":"essential","source":"https://www.getyourguide.com/antigua-guatemala-l1619/from-antigua-or-guatemala-coffee-culture-full-day-tour-t21818/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Hilltop cross with the classic Antigua panorama framed by Volcan Agua.","when":"year-round","commission":"bundled into commissionable city tour"},{"name":"Santo Domingo del Cerro sculpture park","si_tag":"Culture & Heritage","status":"future","hook":"Hilltop art-and-garden annex above Casa Santo Domingo with city + volcano views; free hotel shuttle.","bookable_category":"free / hotel shuttle add-on","tier":"essential","source":"https://www.casasantodomingo.com.gt/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Hilltop art-and-garden annex above Casa Santo Domingo with city + volcano views; free hotel shuttle.","when":"Semana Santa  late Mar/early Apr","commission":"pairs with Casa Santo Domingo stay (hotel AOR)"},{"name":"Jade museum + workshop","si_tag":"Culture & Heritage","status":"future","hook":"Working jade ateliers demonstrating Guatemala''s Maya jade tradition; high-margin retail tie-in.","bookable_category":"guided artisan tour","tier":"premier","source":"https://www.dlgcoffee.org/coffee-tour","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Working jade ateliers demonstrating Guatemala''s Maya jade tradition; high-margin retail tie-in.","when":"year-round","commission":"artisan-tour affiliate; retail non-commissionable"},{"name":"Chichicastenango market day-trip","si_tag":"Culture & Heritage","status":"future","hook":"Thursday/Sunday highland Maya market of textiles and masks.","bookable_category":"DMC day tour (cleared corridor)","tier":"comfort","source":"https://www.martsam.com/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Thursday/Sunday highland Maya market of textiles and masks.","when":"Semana Santa  late Mar/early Apr","commission":"DMC 10-12% / affiliate 4-8%"},{"name":"Ciudad Vieja (first colonial capital)","si_tag":"Culture & Heritage","status":"future","hook":"Guatemala''s original 1527 capital, destroyed by a 1541 lahar, just outside Antigua - deep-history layer.","bookable_category":"guided cultural add-on","tier":"essential","source":"https://www.getyourguide.com/antigua-guatemala-l1619/from-antigua-or-guatemala-coffee-culture-full-day-tour-t21818/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Guatemala''s original 1527 capital, destroyed by a 1541 lahar, just outside Antigua - deep-history layer.","when":"Semana Santa  late Mar/early Apr","commission":"bundled into commissionable heritage tour"},{"name":"Finca Filadelfia coffee tour","si_tag":"Culinary","status":"future","hook":"Finca-to-cup tour on an 1870-founded estate, one of Guatemala''s first coffee farms; ~$20, on-site hotel + restaurant.","bookable_category":"coffee-finca tour (direct/Viator)","tier":"comfort","source":"https://www.visit-antigua.com/finca-filadelfia.php","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Finca-to-cup tour on an 1870-founded estate, one of Guatemala''s first coffee farms; ~$20, on-site hotel + restaurant.","when":"Semana Santa  late Mar/early Apr","commission":"Viator affiliate 4-8%; direct pass-through"},{"name":"De la Gente community coffee tour","si_tag":"Culinary","status":"future","hook":"Nonprofit farmer-led tour in San Miguel Escobar (~4 hr, ~$38 incl. shuttle + beans) - responsible-tourism moat.","bookable_category":"community coffee tour","tier":"essential","source":"https://www.dlgcoffee.org/coffee-tour","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Nonprofit farmer-led tour in San Miguel Escobar (~4 hr, ~$38 incl. shuttle + beans) - responsible-tourism moat.","when":"Semana Santa  late Mar/early Apr","commission":"affiliate/donation model; largely pass-through - brand-values proof point"},{"name":"Guatemalan cooking class","si_tag":"Culinary","status":"future","hook":"Hands-on colonial-kitchen class (pepian, tamales, tortillas); rainy-day-proof culinary depth.","bookable_category":"Viator/GetYourGuide class","tier":"comfort","source":"https://www.getyourguide.com/antigua-guatemala-l1619/from-antigua-or-guatemala-coffee-culture-full-day-tour-t21818/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Hands-on colonial-kitchen class (pepian, tamales, tortillas); rainy-day-proof culinary depth.","when":"Semana Santa  late Mar/early Apr","commission":"affiliate 4-8%"},{"name":"Sumpango Barriletes Gigantes giant-kite festival","si_tag":"Wildlife & Nature","status":"future","hook":"40-ft+ handmade kites flown in the cemetery on All Saints'' Day (Nov 1) to commune with the dead.","bookable_category":"DMC day tour (Nov 1 only)","tier":"comfort","source":"https://tropicanahostel.com/antigua-weather-what-to-expect-and-the-best-time-to-visit/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","blurb":"40-ft+ handmade kites flown in the cemetery on All Saints'' Day (Nov 1) to commune with the dead.","when":"Semana Santa  late Mar/early Apr","commission":"DMC 10-12% / affiliate 4-8%; entry pass-through"}],"faq":[{"q":"How hard is the Acatenango overnight volcano trek?","a":"It''s a serious guided overnight — roughly 1,570 m of ascent to a 3,976 m summit over a 10–12-hour trek split across two days, with base camp near 3,500 m. It''s worth it because you watch Fuego erupt through the night, but altitude and cold are real, so TWW sells reputable guided operators only.","source":"theworldtravelguy.com, Accessed 2026-07-06","si_tag":"expedition"},{"q":"Is Antigua a good place for a wedding or honeymoon?","a":"Yes — Antigua is a genuinely rising colonial-wedding city, because its converted-palace boutique hotels deliver character at the luxury-boutique level: Casa Santo Domingo (5-star, #11 of 102, 4.6★, 2,724 reviews), palace-suite Palacio de Doña Leonor, and adults-only 26-room Pensativo House. Colonial weddings book 9–12 months ahead.","source":"tripadvisor.com, Accessed 2026-07-06","si_tag":"romance"},{"q":"When is Semana Santa 2027 and how far ahead should I book?","a":"Book about a year ahead. Semana Santa 2027 runs ~March 24–28 (Good Friday Mar 26), the most famous Holy Week in the Americas, and Antigua has limited hotel inventory — \"the best places sell out months in advance.\" Fire the booking a full year out, with a \"book by January\" last-call.","source":"livinginguatemala.com, Accessed 2026-07-06","si_tag":"culture"},{"q":"Can I tour a coffee farm from Antigua?","a":"Yes, minutes from the plaza. Finca Filadelfia — founded 1870 as one of Guatemala''s first coffee farms — runs ~2-hour finca-to-cup tours (~$20), and nonprofit De la Gente runs a ~4-hour farmer-led tour in San Miguel Escobar (~$38 incl. shuttle + beans), because Antigua is a premier coffee origin.","source":"visit-antigua.com, Accessed 2026-07-06","si_tag":"culinary"},{"q":"Does Antigua have spa and wellness options?","a":"Yes — the anchor is the 5-star Hotel Museo Spa Casa Santo Domingo, whose spa sits alongside six on-site museums inside 16th-century Dominican monastery ruins, making it Antigua''s iconic wellness-and-culture address. It''s a quiet colonial-retreat market rather than a resort-spa one.","source":"tripadvisor.com, Accessed 2026-07-06","si_tag":"wellness"},{"q":"Can I see the giant-kite festival from Antigua?","a":"Yes, as a Nov 1 day-trip. The Sumpango Barriletes Gigantes festival flies 40-ft+ handmade kites in the cemetery on All Saints'' Day to commune with the dead — visually stunning and uniquely Guatemalan, an easy DMC day tour from Antigua.","source":"tropicanahostel.com, Accessed 2026-07-06","si_tag":"wildlife"},{"q":"What''s the real risk to plan for on Acatenango?","a":"Cold, not lava. Base-camp temperatures drop to 0 °C to −5 °C; on January 8, 2017, six Guatemalan hikers died of hypothermia on Acatenango after arriving unprepared — an exposure/preparation failure, not a lava event. Book only reputable guided operators who supply proper down layers, tents and a real sleeping system.","source":"theworldtravelguy.com, Accessed 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Antigua Guatemala Travel Guide 2026 — Volcanoes, Semana Santa & Colonial Weddings | TravelWell.World","meta_description":"Plan Antigua Guatemala: the Acatenango/Fuego overnight volcano trek (guided-only, 3,976 m), world-famous Semana Santa alfombras, coffee fincas, colonial-wedding hotels, and straight L3 State-Dept-cleared safety.","slug":"antigua-guatemala","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":["en","es-GT"],"local_keywords":["qué hacer en Antigua Guatemala","Acatenango tour","Semana Santa Antigua","bodas Antigua Guatemala","tour de café Antigua","volcán Pacaya Antigua","hoteles de lujo Antigua Guatemala","alfombras Semana Santa"],"hreflang":["en","es-GT"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"future"},{"si":"culinary","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Hotel Museo Spa Casa Santo Domingo","why_ultra":"5-star in 16th-c. Dominican monastery ruins; six museums + spa; #11 of 102 Antigua hotels; Antigua''s iconic top-of-market address","earning":"on application / host-Virtuoso or Fora where eligible","virtuoso_value_add":"consortia amenities where eligible (verify)","mor":true,"tier":"luxury"},{"name":"Palacio de Dona Leonor","why_ultra":"converted colonial palace, antique-furnished grand suites in the historic core; romance/honeymoon standout","earning":"on application / Fora lane where eligible","virtuoso_value_add":"consortia amenities where eligible (verify)","mor":true,"tier":"luxury"},{"name":"Pensativo House","why_ultra":"26-room adults-only boutique (Porta Hotels), garden + rooftop + spa, steps off Central Park; honeymoon fit","earning":"on application / Fora lane","virtuoso_value_add":"consortia amenities where eligible (verify)","mor":true,"tier":"luxury"}],"source_verified":"2026-07-06","hero":{"query":"Antigua, Guatemala"},"geo":{"lat":14.5586,"lng":-90.7295}}'::jsonb, 5),
  ('arequipa-colca-canyon-peru', '10S', 'Arequipa & the Colca Canyon, Peru', 'Peru', 'White stone, three volcanoes, one canyon', 'live', 'verified', 'mountainValley', 'Lima, South Coast & Amazon', '{"expedition","romance","culture"}', '{}', '{"essential","comfort","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"105","tourist_assistance":"iPerú","advisory_level":"L2","book_enabled":true,"bin":"freely bookable (L2)","air_access_verified":true,"air_access":"Rodríguez Ballón International (AQP) via Lima (LIM)","altitude_m":{"arequipa":2335,"chivay":3650,"canyon_rim":3800,"patapampa_pass":4910,"misti_summit":5822,"chachani_summit":6057},"water":"bottled/filtered","volcano_note":"El Misti active, monitored — no routine risk to city visitors","medevac":"Arequipa clinics stabilize; serious cases evac to Lima","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel Within 20km south of the Peru-Colombia border FCDO advises against all but essential travel to areas within 20km south of the Putumayo River and the border between Peru and Colombia (Loreto region) except for: the Amazon River the area of the triple border with Brazil and Colombia from and including the towns of Caballococha in Peru up to the actual triple border at Santa Rosa de Yavari town Valley of the Apurímac, Ene, and Mantaro Rivers ( VRAEM ) FCDO advises against all but essential travel to the Valley of the Apurímac, Ene, and Mantaro Rivers, also known as the VRAEM region."},{"form":"against all but essential travel","text":"advise against all but essential travel to these two areas for safety and security reasons."},{"form":"against all but essential travel","text":"advises against all but essential travel to areas within 20km south of the Putumayo River and the border between Peru and Colombia (Loreto region) except for: the Amazon River the area of the triple border with Brazil and Colombia from and including the towns of Caballococha in Peru up to the actual triple border at Santa Rosa de Yavari town This is due to a high level of violence from organised criminal gangs who produce and traffic illegal drugs."},{"form":"against all but essential travel","text":"advises against all but essential travel to the Valley of the Apurímac, Ene and Mantaro Rivers, also known as the VRAEM region."},{"form":"against all but essential travel","text":"advises against all but essential travel."}],"url":"https://www.gov.uk/foreign-travel-advice/peru","read":"2026-08-19","page_updated":"2026-06-22T23:35:12+01:00"}},"timing":{"peak":"April–November (dry season); condors best 9–11 a.m. year-round","green":"December–March (wet season)","inflection":"late March–early April (dry-season open); mid-to-late August (Arequipa founding anniversary)","fire_date":"mid-to-late March (adventure push) and late July / early August (anniversary push)","booking_lead":"3–6 months for peak / honeymoon at small-inventory ultra properties"},"jewels":[{"name":"Cruz del Cóndor","si_tag":"expedition","tier":"comfort","source":"https://turismoliberty.pe/en/arequipa-5-day-itinerary-2026/","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Early-morning, high-altitude roadside viewpoint, cold, crowded rail edges Typically guided day/2-day tour; low physical risk but altitude + early start","si":"expedition","blurb":"Early-morning, high-altitude roadside viewpoint, cold, crowded rail edges Typically guided day/2-day tour; low physical risk but altitude + early start","when":"April–November","commission":"guided 1-/2-day Colca tour (net-rate)"},{"name":"Colca Canyon multi-day trek","si_tag":"expedition","tier":"comfort","source":"https://www.onmycanvas.com/hike-colca-canyon-arequipa-peru/","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"~1,200 m descent then ~1,200 m ascent; steep switchbacks, heat on the climb-out, AMS exposure the whole way Guided recommended","si":"expedition","blurb":"~1,200 m descent then ~1,200 m ascent; steep switchbacks, heat on the climb-out, AMS exposure the whole way Guided recommended","when":"April–November","commission":"guided trek (net-rate, AOR-eligible)"},{"name":"Patapampa pass & vicuña flats","si_tag":"expedition","tier":"comfort","source":"https://turismoliberty.pe/en/arequipa-5-day-itinerary-2026/","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"April–November","commission":"included in Colca tour"},{"name":"Misti & Chachani summits","si_tag":"expedition","tier":"comfort","source":"https://www.colcatours.com/mismi.htm","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"High-altitude mountaineering; Chachani is one of the \"easier\" 6,000 m peaks but still a serious ascent; cold, AMS, exertion Guided only","si":"expedition","blurb":"High-altitude mountaineering; Chachani is one of the \"easier\" 6,000 m peaks but still a serious ascent; cold, AMS, exertion Guided only","when":"April–November","commission":"certified mountaineering operator (net-rate)"},{"name":"Río Chili rafting","si_tag":"expedition","tier":"comfort","source":"https://www.ericadventures.com/en/arequipa/chili-rafting-tour-arequipa/","timing":"April–November","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Class II–IV rapids between Misti and Chachani; cold water, altitude Guided/outfitter only. Confirm water-safety gear before booking","si":"expedition","blurb":"Class II–IV rapids between Misti and Chachani; cold water, altitude Guided/outfitter only. Confirm water-safety gear before booking","when":"April–November","commission":"rafting outfitter (net-rate)"},{"name":"Chivay & La Calera hot springs","si_tag":"expedition","tier":"comfort","source":"https://www.p